                    id: "setup".into(),
                    status: Status::Passed,
                    duration_ms: 2,
                    message: String::new(),
                }],
                checks: vec![CheckResult {
                    id: "heads".into(),
                    kind: "heads_converge".into(),
                    status,
                    duration_ms: 5,
                    expected: json!({ "max_lag": 5 }),
